const KEY='museradar-workspace-v3';
let dbPromise;
function db(){if(!globalThis.indexedDB)return Promise.resolve(null);return dbPromise||=(new Promise((resolve,reject)=>{const request=indexedDB.open('museradar-workspace',1);request.onupgradeneeded=()=>request.result.createObjectStore('workspace');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);}));}
export async function loadWorkspace(){const store=await db();if(!store){try{return JSON.parse(localStorage.getItem(KEY));}catch{return null;}}return new Promise((resolve,reject)=>{const req=store.transaction('workspace').objectStore('workspace').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
let queue=Promise.resolve();
export function saveWorkspace(value){const snapshot=structuredClone(value);queue=queue.catch(()=>{}).then(async()=>{const store=await db();if(!store){localStorage.setItem(KEY,JSON.stringify(snapshot));return;}await new Promise((resolve,reject)=>{const tx=store.transaction('workspace','readwrite');tx.objectStore('workspace').put(snapshot,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('保存被中止'));});});return queue;}
export function migrate(museum,resources,posts){let prior;try{prior=JSON.parse(localStorage.getItem('museradar-real-v2'));}catch{}const reviews=Object.fromEntries(Object.entries(prior?.reviews||{}).map(([id,status])=>[id,{status}]));return {version:3,museum:prior?.museum||structuredClone(museum),resources:prior?.resources||structuredClone(resources),posts:prior?.posts||structuredClone(posts),reviews,assessments:{},tasks:[],plans:{},mode:'ai',filters:{},scopeDays:90,includeHistory:false,backendUrl:'',audit:[]};}
